extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var magic_nums: PackedStringArray = magic_numbers("res://rock.gd")
	if not check("no_magic_numbers", magic_nums.is_empty(), "Non devono esserci numeri sparsi dentro le funzioni di rock.gd (trovati: %s)" % [str(magic_nums)]):
		return
	var untyped: int = untyped_declarations("res://rock.gd")
	check("all_typed", untyped == 0, "Tutte le variabili, parametri e funzioni di rock.gd devono avere il tipo esplicito")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var rock_scene := instantiate_scene("res://rock.tscn")
	if not check("rock_scene", rock_scene != null, "La scena res://rock.tscn deve potersi istanziare senza errori"):
		return
	var start_pos := rock_scene.position
	await wait_physics_frames(5)
	check("rock_moves", rock_scene.position.y > start_pos.y, "La roccia deve continuare a cadere lungo l'asse Y")
	var damage_dealt = call_if_exists(rock_scene, "check_hit", [rock_scene.position], 0)
	check("rock_hits", typeof(damage_dealt) == TYPE_INT and damage_dealt > 0, "check_hit() alla stessa posizione deve restituire il danno inflitto")
	rock_scene.position = Vector2(0.0, 700.0)
	await wait_frames(2)
	check("rock_resets", rock_scene.position.y < 200.0, "Oltrepassando i margini dello schermo la roccia deve tornare in alto")

